#!name=人民日报
#!desc=fmz200/wool_scripts · 某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思

[MITM]
hostname = app.peopleapp.com, stat.peopleapp.com, adstatic.peopleapp.com

[Rewrite]
request if ${url} ~= /^https?:\/\/app\.peopleapp\.com\/Api\/\d+\/HomeApi\/(adv|getAdvertImage)/i then reject(404)
request if ${url} ~= /^https?:\/\/stat\.peopleapp\.com\//i then reject(404)
request if ${url} ~= /^https?:\/\/adstatic\.peopleapp\.com\/upload\/AppLoad\/.*.(jpg|png)/i then reject(200)
